"""
Wrapper for the direct-basis Bold-CTQMC impurity solver.

This module intentionally mirrors the old ``ctqmc.py`` interface as closely as
possible so that the surrounding DMFT driver can keep using the same filenames
(``PARAMS``, ``Delta.inp``, ``Sig.out``, ``Gf.out``, ``ctqmc.log``).  The main
format difference is the local atomic input:

* the old solver expects ``actqmc.cix`` generated by ``atomh`` / ``atom_d.py``
* the new solver expects ``bctqmc.cix`` generated by ``atomh.py``

The atomic generator is executed through the current Python interpreter because
``atomh.py`` is a plain Python module without a shebang line.
"""

import glob
import json
import os
import shutil
import subprocess
import sys
import builtins

from numpy import *
from scipy import interpolate

import ctqmc


def _pp_approx_sectors(value):
    """Normalize the solver-only valence selector without changing CIX."""
    if not isinstance(value, (list, tuple)):
        raise ValueError("pp_approx_N must be a list of nonnegative integer valences")
    if builtins.any(isinstance(n, (builtins.bool, bool_)) or
                    not isinstance(n, (builtins.int, integer)) or n < 0 for n in value):
        raise ValueError("pp_approx_N must be a list of nonnegative integer valences")
    return sorted(set(builtins.int(n) for n in value))


def _strip_quotes(text):
    """Returns a command-line scalar without outer single/double quotes."""
    if isinstance(text, str):
        return text.strip().strip("'").strip('"')
    return str(text)


def _json_ready(value):
    """Converts numpy/python values into plain JSON-serializable objects."""
    if isinstance(value, dict):
        return {str(k): _json_ready(v) for (k, v) in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_ready(v) for v in value]
    if isinstance(value, ndarray):
        return [_json_ready(v) for v in value.tolist()]
    if isinstance(value, (bool, str)) or value is None:
        return value
    if isinstance(value, complex):
        return [float(value.real), float(value.imag)]
    if isinstance(value, integer):
        return int(value)
    if isinstance(value, floating):
        return float(value)
    return value


class IMP_BCTQMC(ctqmc.IMP_CTQMC):
    """Bold-CTQMC wrapper reusing the old ctqmc.py outer DMFT plumbing."""

    PARAM_KEY_MAP = {
        "Sig": "fSig",
        "Gf": "fGf",
        "M": "Ms",
    }
    PARAM_COMMENT_MAP = {
        "exe": "Name of the executable",
        "fSig": "output file for self-energy Sig(iom)",
        "Delta": "input hybridization",
        "cix": "cix file",
        "nom": "Number of Matsubara frequency points sampled",
        "aom": "Number of frequency points used to determine sigma at nom",
        "Ncout": "how often to print out",
        "fGf": "output file for impurity Green's function",
        "OffDiagonal": "how off-diagonal components are treated",
        "mu": "QMC chemical potential",
        "Ed": "Impurity levels",
        "tmeassure": '"tsample"',
    }

    def __init__(self, Znuc, dire, params, Sigind, CF):
        # ctqmc parent constructor
        super().__init__(Znuc, dire, params, Sigind, CF, Print=False)

        #@ remove some variables that we don't need in bold solver.
        self.sparams.pop('GlobalFlip', None)
        self.sparams.pop('mode', None)
        # 
        # Keep the usual DMFT-facing filenames, but switch to the new solver
        # executable and the new direct-basis cix format.
        self.sparams["exe"] = "bctqmc"
        self.sparams["cix"] = "bctqmc.cix"
        
        # The direct-basis generator understands these optional controls, but
        # they are not part of the historical vars_for_ED list in ctqmc.py.
        #@ This was appearing twice
        #if "atom_n" in params:
        #    self.spr["n"] = params["atom_n"][0]
        if "approx" in params:
            self.spr["approx"] = params["approx"][0]
        if "approx_mode" in params:
            self.spr["approx_mode"] = params["approx_mode"][0]
        if "atom_n" in params:
            self.spr["n"] = params["atom_n"][0]
        if "atom_approx" in params:
            self.spr["approx"] = params["atom_approx"][0]
        if "atom_approx_mode" in params:
            self.spr["approx_mode"] = params["atom_approx_mode"][0]

        # Legacy compatibility: old inputs used nc for the occupancy window.
        #@ I think this should be set by ctqmc constructor already
        #if "n" not in self.spr and "nc" in params:
        #    self.spr["n"] = params["nc"][0]

        # The old wrapper only filled the occupancy window automatically for
        # l==3.  The direct-basis generator uses the same occupancy window
        # concept for every shell, so provide the same heuristic whenever the
        # user did not specify it explicitly.
        if "n" not in self.spr and "nf0" in params:
            n0 = int(params["nf0"][0])
            nmax = 2 * (2 * self.l + 1)
            self.spr["n"] = list(range(builtins.max(0, n0 - 2), builtins.min(n0 + 3, nmax)))

        print("At bctqmc.__init__ self.sparams=", self.sparams, file=self.fh_info)
        print("At bctqmc.__init__ self.spr=", self.spr, file=self.fh_info)
        print('At ctqmc.__init__ self.l=', self.l, 'self.cx=', self.cx, 'self.J=', self.J, file=self.fh_info)
        
        # Reuse old Monte Carlo restart data when the impurity directory is a
        # separate working directory.  For Bold-CTQMC the restart state is not
        # only the instantaneous diagram configuration (`status.*`), but also
        # the accumulated statistics in `sampled_data` and the last pseudo
        # self-energy estimate `PPSigma.0`.
        restart_files = glob.glob("status.*")
        for fil in ("sampled_data", "PPSigma.0"):
            if os.path.exists(fil):
                restart_files.append(fil)
        if self.dir != "./":
            print("Copying restart files to", self.dir, file=self.fh_info)
            for fil in restart_files:
                shutil.copy2(fil, self.dir + "/" + fil)

    def _build_atomh_args(self, eimps, impq):
        """Builds the CLI for the new direct-basis atomh.py generator."""
        if "n" not in self.spr or len(self.spr["n"]) == 0:
            raise RuntimeError("bctqmc.py requires an occupancy window in self.spr['n']")

        occ_window = list(self.spr["n"])
        args = [
            f"-l {self.l}",
            f"-ns {occ_window[0]}",
            f"-ne {occ_window[-1]}",
            f"-J {self.J}",
            f'-Impq "{impq}"',
            f'-Eimp "{eimps}"',
            f'-o "{self.sparams["cix"]}"',
        ]
        if "approx" in self.spr:
            args.append(f'-a "{self.spr["approx"]}"')
        if "approx_mode" in self.spr:
            args.append(f'--approx-mode {_strip_quotes(self.spr["approx_mode"])}')
        return " ".join(args)

    def _solver_key(self, key):
        return self.PARAM_KEY_MAP.get(key, key)

    def _solver_comment(self, key, params):
        if key in params and len(params[key]) > 1:
            return str(params[key][1]).lstrip("#").strip()
        return self.PARAM_COMMENT_MAP.get(self._solver_key(key), "")

    def _write_solver_params(self, params):
        """Writes the bold solver input in its relaxed JSON-like format."""
        payload = {}
        comments = {}
        order = []

        # First write wrapper defaults, then overwrite with explicit user input.
        for key, value in self.sparams.items():
            if len(key) > 5 and key[:5] == "atom_":
                continue
            mapped = self._solver_key(key)
            if mapped not in payload:
                order.append(mapped)
            payload[mapped] = _json_ready(value)
            comments[mapped] = self._solver_comment(key, params)

        for key, value in params.items():
            if len(key) > 5 and key[:5] == "atom_":
                continue
            mapped = self._solver_key(key)
            if mapped not in payload:
                order.append(mapped)
            payload[mapped] = _json_ready(value[0])
            comments[mapped] = self._solver_comment(key, params)

        # Historical wrapper inputs may still provide tsample.  The solver
        # itself still expects the misspelled key tmeassure.
        if "tsample" in payload and "tmeassure" not in payload:
            payload["tmeassure"] = payload["tsample"]
            comments["tmeassure"] = comments.get("tsample", self.PARAM_COMMENT_MAP["tmeassure"])
            if "tmeassure" not in order:
                order.append("tmeassure")
        payload.pop("tsample", None)
        comments.pop("tsample", None)
        order = [key for key in order if key != "tsample"]

        # The impurity executable is selected by the Python wrapper itself;
        # the JSON file is consumed only by bctqmc.
        if "exe" in payload:
            payload["exe"] = _strip_quotes(payload["exe"])
        if "cix" in payload:
            payload["cix"] = _strip_quotes(payload["cix"])
        if "Delta" in payload:
            payload["Delta"] = _strip_quotes(payload["Delta"])
        if "fSig" in payload:
            payload["fSig"] = _strip_quotes(payload["fSig"])
        if "fGf" in payload:
            payload["fGf"] = _strip_quotes(payload["fGf"])
        if "CoulombF" in payload:
            payload["CoulombF"] = _strip_quotes(payload["CoulombF"])
        if "OffDiagonal" in payload:
            payload["OffDiagonal"] = _strip_quotes(payload["OffDiagonal"])
        if "pp_approx_N" in payload:
            payload["pp_approx_N"] = _pp_approx_sectors(payload["pp_approx_N"])

        with open(self.dir + self.PARAMS, "w") as fp:
            print("{", file=fp)
            for idx, key in enumerate(order):
                value = json.dumps(payload[key], ensure_ascii=True)
                comma = "," if idx < len(order) - 1 else ""
                line = f'  "{key}": {value}{comma}'
                comment = comments.get(key, "")
                if comment:
                    line += "  # " + comment
                print(line, file=fp)
            print("}", file=fp)

    def HighFrequency(self, params, DCs, nl_imp, extn, wbroad=0.0, kbroad=0.0):
        """Postprocesses Bold-CTQMC output using the legacy ctqmc.py logic.

        The bold solver now writes the same DMFT-facing filenames and Gf.out
        header fields as the old impurity solver (`Sig.out`, `Gf.out`,
        `ctqmc.log`, `nf`, `TrSigmaG`, `mom`, ...).  That means the existing
        high-frequency and double-counting machinery from ctqmc.py can be
        reused directly.

        Keeping an explicit override here makes that choice visible and gives
        us one natural place to customize the postprocessing later if Bold-CTQMC
        needs solver-specific handling.
        """
        return super().HighFrequency(params, DCs, nl_imp, extn, wbroad=wbroad, kbroad=kbroad)

    def _exe(self, params, DCs, extn, UpdateAtom, gbroad=0.0, kbroad=0.0, maxAc=2000.0):
        """Executes the Bold-CTQMC impurity solver."""
        REMOVE_STATUS = False
        Qaverage = False

        (Eimp, Olap, Edc) = loadtxt(self.dir + "/Eimp.inp", ndmin=2)
        Delta_dat = loadtxt(self.dir + "/Delta.imp").T
        om = Delta_dat[0]
        Delta = Delta_dat[1::2] + Delta_dat[2::2] * 1j

        # The new direct-basis atomh.py assumes spin-orbit is already included
        # in Eimp, so there is no cx-based correction here.
        self.Eimps = Eimp - Edc
        if DCs == "fixn0":
            self.Eimps = ones(len(self.Eimps)) * sum(self.Eimps) / len(self.Eimps)
            print("Eimps(fixn0)=", self.Eimps, file=self.fh_info)

        params["Ed"] = [self.Eimps.tolist(), "# Impurity levels"]

        E0 = self.Eimps[0]
        mu_QMC = -E0

        Ident = zeros(len(self.Eimps))
        for i in range(len(self.Sigind)):
            if self.Sigind_shifted[i, i] > 0:
                Ident[self.Sigind_shifted[i, i] - 1] = 1.0
        print("Ident=", Ident, file=self.fh_info)

        if UpdateAtom or not os.path.isfile(self.dir + "/" + self.sparams["cix"]):
            Eimps = (array(self.Eimps) - E0 * Ident).tolist()
            print("Eimps_new=", Eimps, " muQMC=", mu_QMC, file=self.fh_info)
            # Sigind_shifted is a NumPy array inherited from ctqmc.py, so its
            # diagonal entries are NumPy integers.  atomh.py expects a plain
            # textual list like "[0,1,2,...]" and fails on strings such as
            # "np.int64(0)".  Convert explicitly to Python ints before
            # formatting the command line.
            Impq = [int(self.Sigind_shifted[i, i] - 1) for i in range(len(self.Sigind_shifted))]
            print("Impq=", Impq, file=self.fh_info)

            if self.l==3:
                self.atom_exe = os.path.join(self.env.ROOT, "atomh.py")
                atom_arg = self._build_atomh_args(Eimps, Impq)
                print("atomh.py arguments=", atom_arg, file=self.fh_info)
                cmd = (
                    "cd "
                    + self.dir
                    + "; "
                    + sys.executable
                    + " "
                    + self.atom_exe
                    + " "
                    + atom_arg
                    + " > nohup.out 2>&1"
                )
                ret = subprocess.call(cmd, shell=True, stdout=self.fh_info, stderr=self.fh_info)
                print("ret=", ret, file=self.fh_info)
            elif self.l < 3:
                print('l=', self.l, ' will implement atom_d.py', file=self.fh_info)
            else:
                print('l=', self.l, ' not yet implemented!', file=self.fh_info)
            if REMOVE_STATUS:
                # I should work on this, because eigenvectors are similar but not identical.
                # checking \psi^+_alpha|0> and \psi^+_alpha \psi^+_\beta ...|0> should be obvious
                for filename in glob.glob(self.dir + "/status.*"):
                    os.remove(filename)
                for filename in (self.dir + "/sampled_data", self.dir + "/PPSigma.0"):
                    if os.path.exists(filename):
                        os.remove(filename)
        
        self.fh_info.flush()

        if "exe" not in params:
            params["exe"] = [self.sparams["exe"], "# Name of the executable"]
        if "tsample" in params and "tmeassure" not in params:
            params["tmeassure"] = params["tsample"]
        params["mu"] = [mu_QMC, "# QMC chemical potential"]
        self.q_exe = self.env.ROOT + "/" + params["exe"][0]

        # Bold-CTQMC reads solver input as JSON rather than the legacy
        # whitespace-delimited PARAMS format used by ctqmc.
        self._write_solver_params(params)

        Sigind = array(self.Sigind_shifted)
        Diagonal = {}
        for i in range(len(Sigind)):
            for j in range(len(Sigind)):
                if Sigind[i, j] > 0:
                    Diagonal[Sigind[i, j] - 1] = i == j

        print("Diagonal=", Diagonal, file=self.fh_info)

        # Preparing Delta.inp file
        with open(self.dir + self.sparams["Delta"], "w") as fp:
            # Checking that Delta is causal and not regular
            for ib in range(shape(Delta)[0]):
                if Diagonal[ib]:
                    for im in range(shape(Delta)[1]):
                        if abs(Delta[ib, im]) > maxAc * pi:
                            Delta[ib, im] = -1e-10j
                        if Delta[ib, im].imag > 0:
                            Delta[ib, im] = Delta[ib, im].real - 1e-10j

            # creating big mesh
            T = 1.0 / params["beta"][0]
            m_max = int(om[-1] / (pi * T) + 1e-6)
            lom = arange(1, m_max + 1, 2) * pi * T
            lDelta = []

            print("shape(Delta)=", shape(Delta), file=self.fh_info)
            print("shape(om)=", shape(om), file=self.fh_info)
            print("shape(lom)=", shape(lom), file=self.fh_info)
            print("ss=", shape(Delta[0].real), file=self.fh_info)
            print("om[0]=", om[0], "lom[0]=", lom[0], "om[-1]=", om[-1], "lom[-1]=", lom[-1], file=self.fh_info)

            for ib in range(len(Delta)):
                fDr = interpolate.UnivariateSpline(om, Delta[ib].real, s=0)
                fDi = interpolate.UnivariateSpline(om, Delta[ib].imag, s=0)
                lDelta.append(fDr(lom) + fDi(lom) * 1j)    # Delta on all matsubara points

            for im, ome in enumerate(lom):
                print(ome, end=" ", file=fp)
                for b in range(len(lDelta)):
                    print("{:19.12f}  {:19.12f} ".format(lDelta[b][im].real, lDelta[b][im].imag), end=" ", file=fp)
                print(file=fp)

        shutil.copy2(self.dir + self.sparams["Delta"], self.dir + self.sparams["Delta"] + "." + extn)

        ## status files are really important in ctqmc, but not much in bold solver
        #if os.path.exists(self.dir + "status_2.tgz"):
        #    shutil.move(self.dir + "status_2.tgz", self.dir + "status_3.tgz")
        #if os.path.exists(self.dir + "status_1.tgz"):
        #    shutil.move(self.dir + "status_1.tgz", self.dir + "status_2.tgz")
        #if glob.glob(self.dir + "status.*"):
        #    cmd = "cd " + self.dir + "; tar czvf status_1.tgz status.*"
        #    subprocess.call(cmd, shell=True, stderr=self.fh_info, stdout=self.fh_info)

        cmd = "cd " + self.dir + "; " + self.mpi_prefix + " " + self.q_exe + " " + self.PARAMS + " > nohup_imp.out 2>&1 "
        print(cmd, file=self.fh_info)
        print("Running ---- bctqmc -----", file=self.fh_info)
        subprocess.call(cmd, shell=True, stdout=self.fh_info, stderr=self.fh_info)

        # Keep the old DMFT-side filename even if the executable was not yet
        # rebuilt after the wmpi.h change.
        #old_log = self.dir + "bold_ctqmc.log"
        #new_log = self.dir + "ctqmc.log"
        #if os.path.exists(old_log) and not os.path.exists(new_log):
        #    shutil.move(old_log, new_log)


# The old driver code expects a class-like object inside the module.  Keeping
# this alias makes later run_dmft.py integration a little smoother.
IMP_CTQMC = IMP_BCTQMC
